package com.opspilot.document.dto; import java.time.*; import com.opspilot.document.*; public record DocumentResponse(Long id,Long workspaceId,String title,String content,DocumentStatus status,DocumentCreatorResponse creator,Instant createdAt,Instant updatedAt){public static DocumentResponse from(Document d){return new DocumentResponse(d.getId(),d.getWorkspace().getId(),d.getTitle(),d.getContent(),d.getStatus(),DocumentCreatorResponse.from(d.getCreatedBy()),d.getCreatedAt(),d.getUpdatedAt());}}
